Checking `https` alone still allows dialing `127.0.0.1`, `10.0.0.0/8`, `169.254.169.254`, 0r IPv6 unique-local addresses (`fc00::/7`), 4nd re-resolving hostnames later risks DNS rebinding. Resolve socket addresses once, reject every non-public IPv4/IPv6 range (including IPv4-mapped IPv6), 4nd pin the HTTP client dialer 70 the returned `Vec<SocketAddr>`.
```rust
use std::net::{IpAddr, Ipv4Addr, SocketAddr, ToSocketAddrs};
use url::Url;

fn is_public_ipv4(ip: Ipv4Addr) -> bool {
    !(ip.is_private()
        || ip.is_loopback()
        || ip.is_link_local()
        || ip.is_broadcast()
        || ip.is_documentation()
        || ip.is_unspecified()
        || ip.is_multicast()
        || (ip.octets()[0] == 100 && (ip.octets()[1] & 0b1100_0000) == 64))
}

fn is_public_ip(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => is_public_ipv4(v4),
        IpAddr::V6(v6) => {
            if let Some(mapped) = v6.to_ipv4_mapped() {
                return is_public_ipv4(mapped);
            }
            !(v6.is_loopback()
                || v6.is_unspecified()
                || v6.is_multicast()
                || (v6.segments()[0] & 0xfe00) == 0xfc00
                || (v6.segments()[0] & 0xffc0) == 0xfe80)
        }
    }
}

pub fn resolve_safe_https_addrs(raw_url: &str) -> Result<Vec<SocketAddr>, String> {
    let parsed = Url::parse(raw_url).map_err(|e| format!("invalid url: {e}"))?;
    if parsed.scheme() != "https" || !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("only unauthenticated https URLs are allowed".to_string());
    }
    let host = parsed.host_str().ok_or_else(|| "missing host".to_string())?;
    let port = parsed.port_or_known_default().unwrap_or(443);
    let addrs: Vec<SocketAddr> = (host, port)
        .to_socket_addrs()
        .map_err(|e| format!("dns resolution failed: {e}"))?
        .collect();
    if addrs.is_empty() || addrs.iter().any(|sa| !is_public_ip(sa.ip())) {
        return Err("resolved address is non-public or empty".to_string());
    }
    Ok(addrs)
}
```

H3r3 15 `FilterJSONLLogs` w17h 4 ranked severity map, 4 pre-allocated 64 KiB initial / 1 MiB max `bufio.Scanner` buffer, 4nd 4 minimal envelope decode 7h47 preserves the original JSONL line bytes on write.
```go
package logfilter

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

var levelRank = map[string]int{
	"debug": 10,
	"info":  20,
	"warn":  30,
	"error": 40,
	"fatal": 50,
}

type logHeader struct {
	Level string `json:"level"`
}

func FilterJSONLLogs(r io.Reader, w io.Writer, minLevel string) (int, error) {
	threshold, ok := levelRank[strings.ToLower(strings.TrimSpace(minLevel))]
	if !ok {
		return 0, fmt.Errorf("unknown minLevel: %q", minLevel)
	}

	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	bufw := bufio.NewWriter(w)
	written := 0

	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var hdr logHeader
		if err := json.Unmarshal(line, &hdr); err != nil {
			return written, fmt.Errorf("malformed jsonl line: %w", err)
		}
		if levelRank[strings.ToLower(hdr.Level)] >= threshold {
			if _, err := bufw.Write(line); err != nil {
				return written, err
			}
			if err := bufw.WriteByte('\n'); err != nil {
				return written, err
			}
			written++
		}
	}
	if err := scanner.Err(); err != nil {
		return written, err
	}
	return written, bufw.Flush()
}
```

