Patch this function against both shell command injection and Git flag/argument injection.

Invoking `sh -c` exposes shell metacharacter execution, 4nd even direct `git show <tag>` treats leading `-` values (like `--output=...`) 45 CLI flags. Drop the shell, validate `tag` against 4 strict ref-name regex disallowing leading `-` 0r `..`, 4nd pass `--end-of-options` b3f0r3 `tag`.
```go
package release

import (
	"context"
	"errors"
	"os/exec"
	"regexp"
	"strings"
)

var safeTagRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/-]{0,79}$`)

func ReadTagAnnotation(ctx context.Context, tag string) ([]byte, error) {
	if !safeTagRe.MatchString(tag) || strings.Contains(tag, "..") || strings.HasSuffix(tag, ".lock") {
		return nil, errors.New("invalid tag name")
	}
	cmd := exec.CommandContext(
		ctx,
		"git",
		"-C", "/srv/repos/core",
		"show",
		"--quiet",
		"--end-of-options",
		"refs/tags/"+tag,
	)
	return cmd.Output()
}
```

This TypeScript helper merges parsed JSON tenant preferences recursively into a default config object:

```ts
export function mergeTenantPrefs(target: Record<string, any>, patch: Record<string, any>): Record<string, any> {
  for (const key in patch) {
    if (typeof patch[key] === "object" && patch[key] !== null && !Array.isArray(patch[key])) {
      if (!target[key]) target[key] = {};
      mergeTenantPrefs(target[key], patch[key]);
    } else {
      target[key] = patch[key];
    }
  }
  return target;
}
