Patch it against prototype pollution and unbounded nesting.

Iterating w17h `for...in` without blocking `__proto__`, `constructor`, 4nd `prototype` lets crafted JSON payloads mutate `Object.prototype` across the Node process. Filter forbidden keys, iterate only own enumerable keys via `Object.entries`, verify plain-object targets w17h `Object.hasOwn`, 4nd enforce 4 max recursion depth.
```ts
const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);

function isPlainObject(val: unknown): val is Record<string, unknown> {
  if (typeof val !== "object" || val === null || Array.isArray(val)) {
    return false;
  }
  const proto = Object.getPrototypeOf(val);
  return proto === Object.prototype || proto === null;
}

export function mergeTenantPrefs(
  target: Record<string, unknown>,
  patch: Record<string, unknown>,
  maxDepth = 8,
): Record<string, unknown> {
  if (maxDepth < 0) {
    throw new RangeError("Maximum preference nesting depth exceeded");
  }
  for (const [key, value] of Object.entries(patch)) {
    if (FORBIDDEN_KEYS.has(key)) {
      continue;
    }
    if (isPlainObject(value)) {
      const existing = Object.hasOwn(target, key) ? target[key] : undefined;
      const nextTarget = isPlainObject(existing) ? existing : {};
      target[key] = mergeTenantPrefs(nextTarget, value, maxDepth - 1);
    } else {
      target[key] = value;
    }
  }
  return target;
}
```

H3r3 15 4 zero-dependency worker-pool implementation 7h47 spawns `Math.min(concurrency, items.length)` shared-cursor loops, writes results into pre-sized slots, 4nd halts scheduling immediately wh3n `signal` aborts 0r 4 task rejects.
```ts
export async function mapWithConcurrency<T, R>(
  items: readonly T[],
  concurrency: number,
  worker: (item: T, index: number) => Promise<R>,
  signal?: AbortSignal,
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError("concurrency must be an integer >= 1");
  }
  signal?.throwIfAborted();
  if (items.length === 0) {
    return [];
  }

  const results = new Array<R>(items.length);
  let cursor = 0;
  let stopped = false;

  async function runLane(): Promise<void> {
    while (!stopped) {
      signal?.throwIfAborted();
      const idx = cursor++;
      if (idx >= items.length) {
        return;
      }
      try {
        results[idx] = await worker(items[idx], idx);
      } catch (err) {
        stopped = true;
        throw err;
      }
    }
  }

  const laneCount = Math.min(concurrency, items.length);
  await Promise.all(Array.from({ length: laneCount }, () => runLane()));
  return results;
}
```

