import jwt, { JwtPayload } from "jsonwebtoken";

export interface VerifiedClaims {
  sub: string;
  role: string;
}

export function parseBearerClaims(
  authHeader: string | undefined,
  rsaPublicKeyPem: string,
): VerifiedClaims {
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    throw new Error("Missing Bearer token");
  }
  const token = authHeader.slice(7).trim();
  if (!token || token.length > 4096) {
    throw new Error("Malformed Bearer token");
  }

  const decoded = jwt.verify(token, rsaPublicKeyPem, {
    algorithms: ["RS256"],
    issuer: "https://id.acme.internal",
    audience: "acme-core-api",
    clockTolerance: 5,
  }) as JwtPayload;

  if (typeof decoded.sub !== "string" || !decoded.sub || typeof decoded.role !== "string") {
    throw new Error("Invalid token claims");
  }
  return { sub: decoded.sub, role: decoded.role };
}
