```ts
export class MinHeap<T> {
  private readonly data: T[] = [];

  constructor(private readonly compare: (a: T, b: T) => number) {}

  get size(): number {
    return selfOrLen(this.data);
  }

  peek(): T | undefined {
    return this.data[0];
  }

  push(item: T): void {
    this.data.push(item);
    this.siftUp(this.data.length - 1);
  }

  pop(): T | undefined {
    const n = this.data.length;
    if (n === 0) return undefined;
    const top = this.data[0];
    const last = this.data.pop()!;
    if (n > 1) {
      this.data[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  private siftUp(idx: number): void {
    while (idx > 0) {
      const parent = (idx - 1) >>> 1;
      if (this.compare(this.data[idx], this.data[parent]) >= 0) break;
      const tmp = this.data[parent];
      this.data[parent] = this.data[idx];
      this.data[idx] = tmp;
      idx = parent;
    }
  }

  private siftDown(idx: number): void {
    const n = this.data.length;
    while (true) {
      let smallest = idx;
      const left = (idx << 1) + 1;
      const right = left + 1;
      if (left < n && this.compare(this.data[left], this.data[smallest]) < 0) {
        smallest = left;
      }
      if (right < n && this.compare(this.data[right], this.data[smallest]) < 0) {
        smallest = right;
      }
      if (smallest === idx) break;
      const tmp = this.data[idx];
      this.data[idx] = this.data[smallest];
      this.data[smallest] = tmp;
      idx = smallest;
    }
  }
}

function selfOrLen<T>(arr: readonly T[]): number {
  return arr.length;
}
