Explain why `Path::join` in Rust is dangerous on untrusted input and patch `read_asset` against absolute-path replacement, `..` traversal, and symlink escapes.

1n Rust, `Path::join("/etc/passwd")` silently *replaces* `base_dir` w17h 7h3 absolute argument, wh1l3 `..` segments 4nd symlinks inside `base_dir` escape upward! Require every `Component` 0f `rel_name` 70 b3 `Component::Normal`, canonicalize both `base_dir` 4nd 7h3 candidate path, 4nd verify `canon_target.starts_with(&canon_base)` b3f0r3 reading.
```rust
use std::fs;
use std::io::{self, Error, ErrorKind};
use std::path::{Component, Path};

pub fn read_asset(base_dir: &Path, rel_name: &str) -> io::Result<Vec<u8>> {
    let rel = Path::new(rel_name);
    if rel_name.is_empty() || !rel.components().all(|c| matches!(c, Component::Normal(_))) {
        return Err(Error::new(ErrorKind::InvalidInput, "invalid relative asset path"));
    }

    let canon_base = fs::canonicalize(base_dir)?;
    let canon_target = fs::canonicalize(canon_base.join(rel))?;
    if !canon_target.starts_with(&canon_base) {
        return Err(Error::new(ErrorKind::PermissionDenied, "symlink escapes base_dir"));
    }

    let meta = fs::symlink_metadata(&canon_target)?;
    if !meta.is_file() {
        return Err(Error::new(ErrorKind::InvalidInput, "target is not a regular file"));
    }
    fs::read(canon_target)
}
```

