CREATE OR REPLACE FUNCTION public.approve_invoices_batch(
    p_tenant_id uuid,
    p_actor_id uuid,
    p_invoice_ids uuid[]
)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    v_expected integer;
    v_updated  integer;
    v_dedup    uuid[];
BEGIN
    IF p_tenant_id IS NULL OR p_actor_id IS NULL OR p_invoice_ids IS NULL THEN
        RAISE EXCEPTION 'tenant_id, actor_id, and invoice_ids are required';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT u), ARRAY[]::uuid[])
      INTO v_dedup
      FROM unnest(p_invoice_ids) AS u
     WHERE u IS NOT NULL;

    v_expected := COALESCE(array_length(v_dedup, 1), 0);
    IF v_expected = 0 THEN
        RETURN 0;
    END IF;

    UPDATE public.invoices
       SET status = 'approved',
           approved_by = p_actor_id,
           approved_at = pg_catalog.now()
     WHERE tenant_id = p_tenant_id
       AND id = ANY(v_dedup)
       AND status = 'pending';

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated <> v_expected THEN
        RAISE EXCEPTION 'batch rejected: expected % pending tenant invoices, matched %', v_expected, v_updated;
    END IF;

    RETURN v_updated;
END;
$$;
